* { box-sizing: border-box; }
:root { --ink: #172554; --muted: #475569; --line: #cbd5e1; --surface: #fff; --accent: #1d4ed8; }
body { margin: 0; font: 1rem/1.55 system-ui, sans-serif; color: var(--ink); background: #f8fafc; }
.site-header { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; padding: 1rem max(1rem, calc((100vw - 76rem) / 2)); background: white; }
.site-header nav { display: flex; flex-wrap: wrap; gap: 1rem; }
a { color: inherit; }
.brand { font-weight: 800; text-decoration: none; }
.page-shell { width: min(calc(100% - 2rem), 76rem); margin-inline: auto; }
.store-hero { padding-block: clamp(2rem, 6vw, 5rem); }
.store-hero h1 { font-size: clamp(2.2rem, 5vw, 4rem); line-height: 1.05; }
.catalog-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: .75rem; padding-block: 1rem; border-block: 1px solid var(--line); }
.catalog-toolbar p { margin-inline-start: auto; color: var(--muted); }
select { font: inherit; padding: .5rem; border-radius: .4rem; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); gap: 1rem; padding-block: 1.5rem 4rem; }
.product-card { min-width: 0; padding: 1rem; border: 1px solid var(--line); border-radius: 1rem; background: var(--surface); }
.product-art { display: grid; place-items: center; aspect-ratio: 4 / 3; border-radius: .75rem; color: #1e3a8a; font-size: 2rem; font-weight: 800; }
.product-art--blue { background: #dbeafe; } .product-art--sand { background: #fef3c7; } .product-art--green { background: #d1fae5; } .product-art--lavender { background: #ede9fe; }
.badge { display: inline-block; padding: .2rem .5rem; border-radius: 99px; background: #dbeafe; color: #1e3a8a; font-size: .78rem; font-weight: 800; }
.badge--sale { background: #fee2e2; color: #991b1b; }
.product-price { font-size: 1.25rem; font-weight: 800; }
.variant-row { display: flex; flex-wrap: wrap; gap: .5rem; margin-block: .75rem; }
.variant-row button { border: 1px solid #64748b; border-radius: 99px; padding: .4rem .75rem; background: white; }
.variant-row button[aria-pressed="true"] { border: 2px solid var(--accent); background: #dbeafe; }
.button { width: 100%; border: 2px solid var(--accent); border-radius: .5rem; padding: .7rem 1rem; background: var(--accent); color: white; font: inherit; font-weight: 700; }
:focus-visible { outline: 3px solid #0f766e; outline-offset: 3px; }
@media (max-width: 38rem) { .catalog-toolbar p { margin-inline-start: 0; width: 100%; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }
